-- The review teams found in a LeanIX inventory export of ArchitectureReview fact sheets (2026-10-30): one row for each different
-- combination of Director, Manager, Enterprise Architect and Solution Architect. Each cell holds email addresses, lower case, sorted and
-- separated by ';' as in the export. review_count is how many fact sheets of the export had the combination.
CREATE TABLE review_team (
    team_id             SERIAL       PRIMARY KEY,
    director            VARCHAR(500),
    manager             VARCHAR(500),
    enterprise_architect VARCHAR(500),
    solution_architect  VARCHAR(500),
    review_count        INTEGER      NOT NULL
);

CREATE UNIQUE INDEX uq_review_team ON review_team (COALESCE(director, ''), COALESCE(manager, ''),
    COALESCE(enterprise_architect, ''), COALESCE(solution_architect, ''));

